script:
(function () {
  'use strict';
  // Needs-based life insurance estimate.
  //   Needs = income replacement + mortgage + other debts + education + final expenses + other needs
  //   Resources = existing life insurance + savings and investments the family could use
  //   Coverage to buy = max(0, needs - resources)
  // Income replacement, two methods:
  //   Detailed: yearly need A = income x share needed - survivor income (Social Security etc.),
  //     paid at the start of each year for n years, rising with inflation g and the unspent payout
  //     earning return r: PV = A x sum_{t=0..n-1} ((1+g)/(1+r))^t = A x (1 - q^n) / (1 - q),
  //     q = (1+g)/(1+r); PV = A x n when r = g.
  //   DIME (Debt, Income, Mortgage, Education): income x years, no discounting or offsets.
  // Verified (Node, scratchpad tests/w3b2e): $64,000/yr for 15 yrs at 5% return / 3% inflation ->
  //   PV $841,986 (closed form above = year-by-year loop $841,985.88); r = g -> A x n;
  //   DIME with $80,000 x 15, $250,000 mortgage, $15,000 debts + $15,000 final expenses, 2 x $50,000
  //   education, less $100,000 cover + $30,000 savings -> $1,450,000.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var mult = new Intl.NumberFormat('en-US', { maximumFractionDigits: 1 });

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }

  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return 0;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function presentValue(annual, years, ret, infl) {
    if (annual <= 0 || years <= 0) return 0;
    var q = (1 + infl) / (1 + ret);
    if (Math.abs(q - 1) < 1e-12) return annual * years;
    return annual * (1 - Math.pow(q, years)) / (1 - q);
  }

  function calculate(o) {
    var annualNeed, income;
    if (o.method === 'dime') {
      annualNeed = o.income;
      income = o.income * o.years;
    } else {
      annualNeed = Math.max(0, o.income * o.share - o.survivor);
      income = presentValue(annualNeed, o.years, o.ret, o.infl);
    }
    var education = o.children * o.perChild;
    var needs = income + o.mortgage + o.debts + education + o.final + o.otherNeeds;
    var resources = o.cover + o.savings;
    return {
      annualNeed: annualNeed, income: income, education: education, needs: needs,
      resources: resources, coverage: Math.max(0, needs - resources), surplus: Math.max(0, resources - needs)
    };
  }

  var IDS = ['liCoverage', 'liNeeds', 'liResources', 'liMultiple', 'liIncomeNeed', 'liMortgageOut',
             'liDebtsOut', 'liEducationOut', 'liFinalOut', 'liOtherOut', 'liCoverOut', 'liSavingsOut', 'liAnnualOut'];

  function clear() {
    IDS.forEach(function (id) { setText(id, '–'); });
    el('liNote').hidden = true;
  }

  function update() {
    var o = {
      method: el('liMethod').value,
      income: read('liIncome'), share: read('liShare') / 100, years: read('liYears'),
      mortgage: read('liMortgage'), debts: read('liDebts'), children: read('liChildren'),
      perChild: read('liPerChild'), final: read('liFinal'), otherNeeds: read('liOtherNeeds'),
      cover: read('liCover'), savings: read('liSavings'), survivor: read('liSurvivor'),
      ret: read('liReturn') / 100, infl: read('liInflation') / 100
    };
    var detailed = o.method !== 'dime';
    el('liDetailed').hidden = !detailed;
    var vals = [o.income, o.share, o.years, o.mortgage, o.debts, o.children, o.perChild, o.final,
                o.otherNeeds, o.cover, o.savings, o.survivor, o.ret, o.infl];
    var err = el('liError');
    var msg = '';
    if (vals.some(isNaN) || vals.some(function (v) { return v < 0; })) msg = 'Enter amounts of zero or more.';
    else if (vals.some(function (v) { return v > 1e11; })) msg = 'One of the amounts is too large.';
    else if (o.years > 70) msg = 'Enter 70 years or fewer of income to replace.';
    else if (o.share > 2) msg = 'Enter an income share of 200% or less.';
    else if (o.ret > 0.3 || o.infl > 0.3) msg = 'Enter a return and inflation rate of 30% or less.';
    else if (o.children > 20 || o.children !== Math.floor(o.children)) msg = 'Enter a whole number of children (up to 20).';
    err.hidden = !msg;
    if (msg) { err.textContent = msg; clear(); return; }

    var r = calculate(o);
    setText('liCoverage', money.format(r.coverage));
    setText('liNeeds', money.format(r.needs));
    setText('liResources', money.format(r.resources));
    setText('liMultiple', o.income > 0 ? mult.format(r.coverage / o.income) + '× income' : '–');
    setText('liIncomeNeed', money.format(r.income));
    setText('liMortgageOut', money.format(o.mortgage));
    setText('liDebtsOut', money.format(o.debts));
    setText('liEducationOut', money.format(r.education));
    setText('liFinalOut', money.format(o.final));
    setText('liOtherOut', money.format(o.otherNeeds));
    setText('liCoverOut', '−' + money.format(o.cover));
    setText('liSavingsOut', '−' + money.format(o.savings));
    setText('liAnnualOut', detailed ? money.format(r.annualNeed) + ' a year for ' + o.years + (o.years === 1 ? ' year' : ' years') : money.format(o.income) + ' × ' + o.years + ' years');

    var note = el('liNote');
    var text = '';
    if (r.surplus > 0) text = 'Your existing cover and savings exceed the needs you entered by ' + money.format(r.surplus) + ', so this estimate suggests no extra cover.';
    else if (detailed && o.ret > o.infl) text = 'The income figure is the lump sum that, invested at ' + (o.ret * 100).toFixed(1).replace(/\.0$/, '') + '%, could pay the yearly amount rising with inflation for ' + o.years + ' years.';
    note.hidden = !text;
    note.textContent = text;
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('liForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
